import * as L from 'leaflet';

import { IMapType } from '@apps/Routes/@types/routes.types';

import { round } from './mathHelper';

export const getArrayFromBounds = (bounds: L.LatLngBounds): Array<[number, number]> => {
  const southWest = bounds.getSouthWest();
  const northEast = bounds.getNorthEast();

  return [
    [round(southWest.lat, 5), round(southWest.lng, 5)],
    [round(northEast.lat, 5), round(northEast.lng, 5)],
  ];
};

export function quadkey(zyx: { z: number; y: number; x: number }): string {
  let result = '';
  for (let i = zyx.z; i > 0; i -= 1) {
    let digit = 0;
    const mask = 1 << (i - 1);

    if ((zyx.x & mask) !== 0) {
      digit += 1;
    }

    if ((zyx.y & mask) !== 0) {
      digit += 1;
      digit += 1;
    }
    result += digit;
  }
  return result;
}

export function distance(lat1: number, long1: number, lat2: number, long2: number): number {
  // радиус Земли
  const R = 6372795;
  // перевод коордитат в радианы

  lat1 *= Math.PI / 180;
  lat2 *= Math.PI / 180;
  long1 *= Math.PI / 180;
  long2 *= Math.PI / 180;

  // вычисление косинусов и синусов широт и разницы долгот
  const cl1 = Math.cos(lat1);
  const cl2 = Math.cos(lat2);
  const sl1 = Math.sin(lat1);
  const sl2 = Math.sin(lat2);
  const delta = long2 - long1;
  const cdelta = Math.cos(delta);
  const sdelta = Math.sin(delta);
  // вычисления длины большого круга
  const y = Math.sqrt(Math.pow(cl2 * sdelta, 2) + Math.pow(cl1 * sl2 - sl1 * cl2 * cdelta, 2));
  const x = sl1 * sl2 + cl1 * cl2 * cdelta;
  const ad = Math.atan2(y, x);
  const dist = ad * R; // расстояние между двумя координатами в метрах
  return dist;
}

export const defaultMapType: IMapType = {
  id: 11,
  name: 'Open Street Map',
  key: 'open_street_map',
  tileUrlTmpl: 'http://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',
  isElliptical: false,
  subdomains: 'abc',
  minZoom: 0,
  maxZoom: 19,
};

const defaultMapOptions: L.MapOptions = {}; //{ attributionControl: false };
export const getMap = (
  element: string | HTMLElement,
  options?: L.MapOptions & { fullscreenControl?: boolean },
): L.Map => new L.Map(element, { ...defaultMapOptions, ...(options ?? {}) });

export const getDefaultTileLayer = (): L.TileLayer => {
  return L.tileLayer('http://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
    attribution: '&copy; <a href="http://osm.org/copyright">OpenStreetMap</a> contributors',
    maxZoom: 20,
    subdomains: 'abc',
    minZoom: 0,
    id: 'osm',
  });
};
export const getForestTileLayer = (): L.TileLayer => {
  return L.tileLayer(
    'https://{s}.tile.thunderforest.com/landscape/{z}/{x}/{y}.png?apikey={apikey}',
    {
      attribution:
        '&copy; <a href="http://www.thunderforest.com/">Thunderforest</a>, &copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
      // eslint-disable-next-line @typescript-eslint/ban-ts-comment
      //@ts-expect-error
      apikey: 'f2b9fd5a71384f37a108e8657a7fae3c',
      maxZoom: 22,
    },
  );
};

export const defaultMapCoordinates = [52.74759, 45.19379] as L.LatLngTuple;
export const defaultMapZoom = 14;

export const setDefaultMapView = (map: L.Map) => {
  map.setView(defaultMapCoordinates, defaultMapZoom);
};
